content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-secondary: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.875rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--spacing-xl) var(--spacing-md);
}

.header {
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.header-description {
  color: var(--text-secondary);
  font-size: var(--font-size-base);
}

.title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: var(--spacing-sm);
}

.card-title {
  font-size: var(--font-size-lg);
  margin-bottom: var(--spacing-md);
}

.main-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-lg);
}

.form-stack {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

@media (min-width: 768px) {
  .main-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 360px) {
  .app-container {
    padding: var(--spacing-md) var(--spacing-sm);
  }
  .card {
    padding: var(--spacing-md);
  }
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: var(--spacing-lg);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-label {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--text-main);
  margin-bottom: var(--spacing-sm);
}

.form-input {
  width: 100%;
  padding: 0.75rem var(--spacing-md);
  font-size: var(--font-size-base);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  background-color: #fff;
  color: var(--text-main);
}

.form-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.summary-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-md);
  margin-top: var(--spacing-md);
}

@media (min-width: 480px) {
  .summary-container {
    grid-template-columns: repeat(3, 1fr);
  }
}

.summary-item {
  background-color: var(--bg-color);
  padding: var(--spacing-md);
  border-radius: 8px;
  border: 1px solid var(--border-color);
  text-align: center;
}

.summary-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-xs);
}

.summary-value {
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--primary-color);
}

.chart-container {
  width: 100%;
  height: 350px;
  margin-top: var(--spacing-md);
}

/**
 * 住宅ローンの入力条件
 */
export interface LoanInput {
  /** 借入金額 (万円), 範囲: 100 ~ 20000 */
  amount: number;
  /** 金利 (%), 範囲: 0.1 ~ 10 */
  interestRate: number;
  /** 返済期間 (年), 範囲: 1 ~ 50 */
  years: number;
  /** ボーナス払い時の年間追加返済額 (万円) - 将来拡張用 */
  bonusAmount?: number;
  /** ボーナス払いの月1 (将来拡張用) */
  bonusMonth1?: number;
  /** ボーナス払いの月2 (将来拡張用) */
  bonusMonth2?: number;
}

/**
 * 年ごとの返済記録
 */
export interface YearlyRecord {
  /** 経過年数 */
  year: number;
  /** 年末時点の借入残高 (円) */
  balance: number;
  /** 年間元本返済額 (円) */
  principalPayment: number;
  /** 年間利息支払額 (円) */
  interestPayment: number;
  /** 年間総支払額 (円) */
  totalPayment: number;
  /** 年間ボーナス返済額 (円) - 将来拡張用 */
  bonusPayment?: number;
}

import { useState, useEffect } from 'react';
import { LoanInput } from './types';
import './index.css';

interface InputFormProps {
  input: LoanInput;
  onChange: (input: LoanInput) => void;
}

export default function InputForm({ input, onChange }: InputFormProps) {
  const [amountStr, setAmountStr] = useState(input.amount.toString());
  const [rateStr, setRateStr] = useState(input.interestRate.toString());
  const [yearsStr, setYearsStr] = useState(input.years.toString());

  useEffect(() => {
    setAmountStr(input.amount.toString());
    setRateStr(input.interestRate.toString());
    setYearsStr(input.years.toString());
  }, [input]);

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAmountStr(val);
    if (val === '') return;
    const num = Number(val);
    if (!isNaN(num)) {
      const clamped = Math.min(20000, Math.max(100, num));
      onChange({ ...input, amount: clamped });
    }
  };

  const handleAmountBlur = () => {
    if (amountStr === '' || isNaN(Number(amountStr))) {
      setAmountStr(input.amount.toString());
    } else {
      const num = Number(amountStr);
      const clamped = Math.min(20000, Math.max(100, num));
      setAmountStr(clamped.toString());
      onChange({ ...input, amount: clamped });
    }
  };

  const handleRateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setRateStr(val);
    if (val === '') return;
    const num = Number(val);
    if (!isNaN(num)) {
      const clamped = Math.min(10, Math.max(0.1, num));
      onChange({ ...input, interestRate: clamped });
    }
  };

  const handleRateBlur = () => {
    if (rateStr === '' || isNaN(Number(rateStr))) {
      setRateStr(input.interestRate.toString());
    } else {
      const num = Number(rateStr);
      const clamped = Math.min(10, Math.max(0.1, num));
      setRateStr(clamped.toString());
      onChange({ ...input, interestRate: clamped });
    }
  };

  const handleYearsChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setYearsStr(val);
    if (val === '') return;
    const num = Number(val);
    if (!isNaN(num)) {
      const clamped = Math.min(50, Math.max(1, num));
      onChange({ ...input, years: clamped });
    }
  };

  const handleYearsBlur = () => {
    if (yearsStr === '' || isNaN(Number(yearsStr))) {
      setYearsStr(input.years.toString());
    } else {
      const num = Number(yearsStr);
      const clamped = Math.min(50, Math.max(1, num));
      setYearsStr(clamped.toString());
      onChange({ ...input, years: clamped });
    }
  };

  return (
    <div className="card">
      <h2 className="title" style={{ fontSize: '1.25rem', marginBottom: '1rem' }}>借入条件の入力</h2>

      <div className="form-group">
        <label className="form-label" htmlFor="amount">借入金額 (万円)</label>
        <input
          id="amount"
          type="number"
          className="form-input"
          value={amountStr}
          onChange={handleAmountChange}
          onBlur={handleAmountBlur}
          min={100}
          max={20000}
          step={100}
          aria-describedby="amount-help"
        />
        <div id="amount-help" style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.25rem' }}>
          100万円から20,000万円の間で入力してください
        </div>
      </div>

      <div className="form-group">
        <label className="form-label" htmlFor="interestRate">金利 (%)</label>
        <input
          id="interestRate"
          type="number"
          className="form-input"
          value={rateStr}
          onChange={handleRateChange}
          onBlur={handleRateBlur}
          min={0.1}
          max={10}
          step={0.05}
          aria-describedby="rate-help"
        />
        <div id="rate-help" style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.25rem' }}>
          0.1%から10%の間で入力してください
        </div>
      </div>

      <div className="form-group">
        <label className="form-label" htmlFor="years">返済期間 (年)</label>
        <input
          id="years"
          type="number"
          className="form-input"
          value={yearsStr}
          onChange={handleYearsChange}
          onBlur={handleYearsBlur}
          min={1}
          max={50}
          step={1}
          aria-describedby="years-help"
        />
        <div id="years-help" style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.25rem' }}>
          1年から50年の間で入力してください
        </div>
      </div>
    </div>
  );
}

import { formatYen } from './utils';
import './index.css';

interface SummaryCardProps {
  monthlyPayment: number;
  totalPayment: number;
  totalInterest: number;
}

export default function SummaryCard({
  monthlyPayment,
  totalPayment,
  totalInterest,
}: SummaryCardProps) {
  const interestRatio = totalPayment > 0 ? (totalInterest / totalPayment) * 100 : 0;

  return (
    <div className="card">
      <h2 className="title" style={{ fontSize: '1.25rem', marginBottom: '1rem' }}>返済シミュレーション結果</h2>
      <div className="summary-container">
        <div className="summary-item">
          <div className="summary-label">毎月の返済額</div>
          <div className="summary-value">{formatYen(monthlyPayment)}</div>
        </div>
        <div className="summary-item">
          <div className="summary-label">総支払額</div>
          <div className="summary-value">{formatYen(totalPayment)}</div>
        </div>
        <div className="summary-item">
          <div className="summary-label">総利息額</div>
          <div className="summary-value">{formatYen(totalInterest)}</div>
          <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.25rem' }}>
            総支払額の {interestRatio.toFixed(1)}%
          </div>
        </div>
      </div>
    </div>
  );
}

import { YearlyRecord } from './types';
import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend
} from 'recharts';
import './index.css';

interface RepaymentChartProps {
  data?: YearlyRecord[];
}

export default function RepaymentChart({ data = [] }: RepaymentChartProps) {
  const formatYenMan = (value: number) => {
    return `${Math.round(value / 10000)}万円`;
  };

  const isEmpty = !data || data.length === 0;

  return (
    <div className="card" role="region" aria-label="返済推移グラフ">
      <h2 className="title" style={{ fontSize: '1.25rem', marginBottom: '1rem' }}>返済推移グラフ</h2>
      <div className="chart-container">
        {isEmpty ? (
          <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%', color: 'var(--text-secondary)' }}>
            データを入力してください
          </div>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={data}
              margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="year" unit="年" stroke="#64748b" />
              <YAxis tickFormatter={formatYenMan} stroke="#64748b" />
              <Tooltip
                formatter={(value: number | string | Array<number | string> | undefined) => [
                  `${Number(value ?? 0).toLocaleString()} 円`,
                  ''
                ]}
                labelFormatter={(label) => `${label}年目`}
              />
              <Legend />
              <Bar dataKey="principalPayment" name="元本返済額" stackId="a" fill="#2563eb" />
              <Bar dataKey="interestPayment" name="利息支払額" stackId="a" fill="#93c5fd" />
              <Line
                type="monotone"
                dataKey="balance"
                name="借入残高"
                stroke="#dc2626"
                strokeWidth={2}
                dot={false}
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}
      </div>
    </div>
  );
}

import { useLoanCalculation } from './useLoanCalculation';
import InputForm from './InputForm';
import SummaryCard from './SummaryCard';
import RepaymentChart from './RepaymentChart';
import './index.css';

export default function App() {
  const {
    input,
    setInput,
    error,
    monthlyPayment,
    totalPayment,
    totalInterest,
    yearlyRecords,
  } = useLoanCalculation({
    amount: 3000,
    interestRate: 1.5,
    years: 35,
  });

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">住宅ローンシミュレーター</h1>
        <p className="header-description">
          借入額・金利・返済期間を入力して、毎月の返済額や推移を確認しましょう。
        </p>
      </header>

      {error && (
        <div className="card" role="alert" style={{ color: '#dc2626', marginBottom: 'var(--spacing-md)' }}>
          {error}
        </div>
      )}

      <main className="main-grid">
        <div className="form-stack">
          <InputForm input={input} onChange={setInput} />
          <SummaryCard
            monthlyPayment={monthlyPayment}
            totalPayment={totalPayment}
            totalInterest={totalInterest}
          />
        </div>
        <div>
          <RepaymentChart data={yearlyRecords} />
        </div>
      </main>
    </div>
  );
}

export const formatYen = (num: number): string => {
  return Math.round(num).toLocaleString() + ' 円';
};

import { useState, useMemo } from 'react';
import { LoanInput, YearlyRecord } from './types';

export function useLoanCalculation(initialInput: LoanInput) {
  const [input, setInput] = useState<LoanInput>(initialInput);
  const [error, setError] = useState<string | null>(null);

  const result = useMemo(() => {
    try {
      setError(null);
      const principal = input.amount * 10000;
      const monthlyRate = input.interestRate / 100 / 12;
      const totalMonths = input.years * 12;

      let monthlyPay = 0;
      if (monthlyRate === 0) {
        monthlyPay = principal / totalMonths;
      } else {
        monthlyPay =
          (principal * monthlyRate * Math.pow(1 + monthlyRate, totalMonths)) /
          (Math.pow(1 + monthlyRate, totalMonths) - 1);
      }

      const tPayment = monthlyPay * totalMonths;
      const tInterest = tPayment - principal;

      const records: YearlyRecord[] = [];
      let currentBalance = principal;

      for (let year = 1; year <= input.years; year++) {
        let yearlyPrincipal = 0;
        let yearlyInterest = 0;

        for (let m = 0; m < 12; m++) {
          if (currentBalance <= 0) break;
          const interestForMonth = currentBalance * monthlyRate;
          let principalForMonth = monthlyPay - interestForMonth;
          if (principalForMonth > currentBalance) {
            principalForMonth = currentBalance;
          }
          yearlyInterest += interestForMonth;
          yearlyPrincipal += principalForMonth;
          currentBalance -= principalForMonth;
        }

        records.push({
          year,
          balance: Math.max(0, Math.round(currentBalance)),
          principalPayment: Math.round(yearlyPrincipal),
          interestPayment: Math.round(yearlyInterest),
          totalPayment: Math.round(yearlyPrincipal + yearlyInterest),
        });
      }

      return {
        monthlyPayment: monthlyPay,
        totalPayment: tPayment,
        totalInterest: tInterest,
        yearlyRecords: records,
      };
    } catch (err) {
      setError('シミュレーションの計算中にエラーが発生しました。入力値を確認してください。');
      return {
        monthlyPayment: 0,
        totalPayment: 0,
        totalInterest: 0,
        yearlyRecords: [],
      };
    }
  }, [input]);

  return {
    input,
    setInput,
    error,
    ...result,
  };
}
